def _num(v):
    return [int(x) for x in re.findall(r"\d+", v or "")]


def is_newer(latest, installed):
    return bool(latest) and (not installed or _num(latest) > _num(installed))


def _state():
    try:
        with open(STATE) as f:
            return json.load(f)
    except (OSError, ValueError):
        return {}


def installed_version(entry):
    """Installed version string, "" when not installed."""
    if entry["kind"] == "appimage":
        tag = _state().get(entry["id"])
        path = os.path.join(HOME, "Applications", entry["asset"])
        return tag if tag and os.path.exists(path) else ""
    path = os.path.expanduser(entry["version_file"])
    try:
        text = open(path).read()
    except OSError:
        return ""
    m = re.search(r'VERSION\s*=\s*"([^"]+)"', text) or re.search(r"(\d+(?:\.\d+)+)", text)
    return m.group(1) if m else "?"


def latest_release(entry):
    """(tag, asset_url) of the newest GitHub release. Network errors raise."""
    req = urllib.request.Request("https://api.github.com/repos/%s/releases/latest" % entry["repo"],
                                 headers={"User-Agent": "vr-autolauncher"})
    with urllib.request.urlopen(req, timeout=15) as r:
        rel = json.load(r)
    url = ""
    for a in rel.get("assets", []):
        if a.get("name") == entry.get("asset"):
            url = a.get("browser_download_url", "")
    return rel.get("tag_name", ""), url


def install_command(entry, tag, asset_url):
    """Shell command that installs/updates the entry (runs in the background)."""
    if entry["kind"] == "script":
        return "curl -fsSL https://raw.githubusercontent.com/%s/main/get.sh | bash" % entry["repo"]
    dest = os.path.join(HOME, "Applications", entry["asset"])
    state = json.dumps(dict(_state(), **{entry["id"]: tag}))
    return ("mkdir -p ~/Applications && curl -fL --retry 2 -o %s.part %s && chmod +x %s.part && mv -f %s.part %s"
            " && mkdir -p %s && printf '%%s' %s > %s"
            % tuple(map(_q, (dest, asset_url, dest, dest, dest, os.path.dirname(STATE), state, STATE))))


def _q(s):
    return "'" + s.replace("'", "'\\''") + "'"
